        </div>
      </section>

      {/* Categories + rows */}
      <section className="mx-auto max-w-shell px-5 py-12 sm:px-8 md:py-16">
        <MenuTabs />

        <p className="mt-10 border-t pt-6 text-[13px] leading-relaxed text-muted">
