"use client";

import { useId, useLayoutEffect, useRef } from "react";
import { useSearchParams } from "next/navigation";
import MenuRow from "@/components/ui/MenuRow";
import site from "@/content/site";

/**
 * Client-side category switcher. Tabs follow the ARIA tabs pattern with
 * roving focus; the active tab is marked by an ink underline.
 */
export default function MenuTabs() {
  const searchParams = useSearchParams();
  const active = site.menu.find((category) => category.id === searchParams.get("category"))?.id ?? site.menu[0].id;
  const tabListRef = useRef<HTMLDivElement>(null);
  const baseId = useId();

  function setActive(category: string) {
    const url = new URL(window.location.href);
    url.searchParams.set("category", category);
    // Update this menu entry without adding a history step or scrolling the page.
    window.history.replaceState(null, "", url);
  }

  useLayoutEffect(() => {
    const list = tabListRef.current;
    if (!list) return;

    function updateHints() {
      if (!list) return;
      list.parentElement!.dataset.scrollLeft = String(list.scrollLeft > 1);
      list.parentElement!.dataset.scrollRight = String(list.scrollLeft + list.clientWidth < list.scrollWidth - 1);
    }

    function revealSelected() {
      if (!list) return;
      const tab = list.querySelector<HTMLElement>('[aria-selected="true"]');
      if (!tab) return;
      const bounds = list.getBoundingClientRect();
      const selected = tab.getBoundingClientRect();
      // Keep a gutter for the overflow hints and focus outline. Only scroll this row.
      if (selected.left < bounds.left + 20) list.scrollLeft -= bounds.left + 20 - selected.left;
      else if (selected.right > bounds.right - 20) list.scrollLeft += selected.right - bounds.right + 20;
      updateHints();
    }

    revealSelected();
    const observer = new ResizeObserver(revealSelected);
    observer.observe(list);
    for (const tab of list.children) observer.observe(tab);
    list.addEventListener("scroll", updateHints, { passive: true });
    return () => {
      observer.disconnect();
      list.removeEventListener("scroll", updateHints);
    };
  }, [active]);

  function activateTab(index: number) {
    const next = site.menu[(index + site.menu.length) % site.menu.length];
    setActive(next.id);
    document.getElementById(`${baseId}-tab-${next.id}`)?.focus({ preventScroll: true });
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    let nextIndex: number | null = null;

    if (event.key === "ArrowRight") nextIndex = index + 1;
    if (event.key === "ArrowLeft") nextIndex = index - 1;
    if (event.key === "Home") nextIndex = 0;
    if (event.key === "End") nextIndex = site.menu.length - 1;
