 const browser=await chromium.launch({channel:'chrome',headless:true});
 const page=await browser.newPage({viewport:{width:320,height:640}});
 await page.goto('http://localhost:3101/menu');
 const list=page.getByRole('tablist');
 await list.scrollIntoViewIfNeeded();
 await page.waitForTimeout(500);
 assert(await page.locator('.menu-tabs-hint-right').isVisible());
 await page.locator('[role=tabpanel]:visible img').evaluateAll(imgs=>Promise.all(imgs.map(img=>img.decode().catch(()=>{}))));
 await page.screenshot({path:'artifacts/menu-check/320-overflow-hint.png'});
 const drinks=page.getByRole('tab',{name:'Drinks'});
 await drinks.click(); await page.waitForTimeout(350);
 await list.evaluate(el=>el.scrollLeft=0);
 await drinks.dispatchEvent('click');
 await page.waitForTimeout(100);
 const b=await drinks.boundingBox(); assert(b.x>=0 && b.x+b.width<=320);
 console.log('Right overflow cue and reselecting an already-selected clipped tab: PASS');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
